CREATE OR REPLACE FUNCTION public.get_org_staff_permissions(_user_id uuid, _organization_id uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  staff_role text;
  base_perms text[];
  override_perms text[];
BEGIN
  SELECT role,
         COALESCE(
           ARRAY(SELECT jsonb_array_elements_text(sections_access)),
           ARRAY[]::text[]
         )
    INTO staff_role, override_perms
    FROM public.org_staff
   WHERE user_id = _user_id AND organization_id = _organization_id
   LIMIT 1;

  IF staff_role IS NULL THEN
    RETURN ARRAY[]::text[];
  END IF;

  base_perms := public.org_role_default_permissions(staff_role);

  -- merge: union of base + overrides (overrides могут только добавлять права)
  RETURN ARRAY(
    SELECT DISTINCT unnest(base_perms || override_perms)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.has_company_access(_user_id uuid, _company_id uuid, _min_role company_staff_role DEFAULT 'viewer'::company_staff_role)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _company_owner UUID;
  _company_org UUID;
  _staff_role public.company_staff_role;
  _role_rank INT;
  _min_rank INT;
BEGIN
  IF _user_id IS NULL OR _company_id IS NULL THEN
    RETURN FALSE;
  END IF;

  IF EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = 'admin') THEN
    RETURN TRUE;
  END IF;

  SELECT user_id, organization_id INTO _company_owner, _company_org
  FROM public.companies WHERE id = _company_id;

  IF _company_owner IS NULL AND _company_org IS NULL THEN
    RETURN FALSE;
  END IF;

  IF _company_owner = _user_id THEN
    RETURN TRUE;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE p.user_id = _user_id
      AND p.organization_id = _company_org
      AND EXISTS (SELECT 1 FROM public.user_roles ur WHERE ur.user_id = _user_id AND ur.role = 'organization')
  ) THEN
    RETURN TRUE;
  END IF;

  IF public.has_org_staff_permission(_user_id, _company_org, 'companies_manage') THEN
    RETURN TRUE;
  END IF;

  SELECT role INTO _staff_role FROM public.company_staff
  WHERE company_id = _company_id AND user_id = _user_id
    AND (expires_at IS NULL OR expires_at > now());

  IF _staff_role IS NULL THEN
    RETURN FALSE;
  END IF;

  _role_rank := CASE _staff_role
    WHEN 'owner' THEN 3 WHEN 'manager' THEN 2 WHEN 'viewer' THEN 1 END;
  _min_rank := CASE _min_role
    WHEN 'owner' THEN 3 WHEN 'manager' THEN 2 WHEN 'viewer' THEN 1 END;

  RETURN _role_rank >= _min_rank;
END;
$function$
